<script>
import { eventBus } from "@/main";
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";

export default {
  name: "TrainingRecommendationResponse",
  mixins: [generalMixin, processQuestionnaire],
  props: ["queries"],
  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/ihris-training-recommendation",
      fhir: {},
      fhirId: "",
      profile:
        "http://ihris.org/fhir/StructureDefinition/training-recommendation-profile",
      isEdit: true,
      overlay: false,
      loading: false,
      accessChecked: false,
      isHR: false,
      allowedFacilities: [],
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      valid: false,
      submitting: false,
      loadingNeeds: true,
      loadingRecommendations: false,

      // Validation rules
      rules: {
        required: (value) => !!value || "This field is required",
        validAge: (value) => {
          if (!value) return true;
          const age = parseInt(value);
          return (age >= 18 && age <= 100) || "Age must be between 18 and 100";
        },
        maxGreaterThanMin: (value) => {
          if (!value || !this.ageFilter.minAge) return true;
          return (
            parseInt(value) > parseInt(this.ageFilter.minAge) ||
            "Maximum age must be greater than minimum age"
          );
        },
      },

      expandedPanels: [],
      expandedFacilities: {},
      searchQuery: "",
      selectedCadre: [],
      filteredNeeds: [],

      // Training Needs
      trainingNeeds: [],
      selectedNeed: [],
      incrementNeed: 0,
      courselevel: null,
      course: null,
      courseother: "",
      country: null,
      recommendationData: {
        title: "",
        institution: "",
        courselevel: null,
        course: null,
        courseother: "",
        country: null,
        trainingtype: "",
        startdate: "",
        enddate: "",
        participants: "",
        location: "",
        methodology: "",
        description: "",
        departments: [],
        designation: [],
        age: [],
      },

      // Age Filter
      ageFilter: {
        type: "",
        minAge: null,
        maxAge: null,
        exactAge: null,
      },

      qualificationConditionTypes: [
        {
          text: "At Least — staff must have this level or higher",
          value: "atleast",
        },
        {
          text: "Maximum — this is the highest qualification staff should have",
          value: "maximum",
        },
      ],

      ageFilterTypes: [
        { text: "No Age Filter", value: "" },
        { text: "Greater Than", value: "greater-than" },
        { text: "Less Than", value: "less-than" },
        { text: "Age Range", value: "range" },
        { text: "Exact Age", value: "exact" },
      ],

      // My Recommendations with Pagination
      myRecommendations: [],
      totalRecommendations: 0,
      recommendationPage: 1,
      recommendationsPerPage: 10,

      // Edit Mode
      editMode: false,
      editingRecommendation: null,

      // Available filters
      availableCadres: [],
      selectedNeedIds: [],
      page: 1,
      itemsPerPage: 20,

      // Array rows for designation and age
      designationRows: [{}],
      ageRows: [{ type: "", minAge: null, maxAge: null, exactAge: null }],
      qualificationRows: [{ level: null, condition: "atleast" }],
      qualificationLevels: [],
      loadingQualificationLevels: false,
      departmentParticipants: {},
      financialYear: {},
    };
  },
  computed: {
    isOtherQualification() {
      return this.course?.reference === "Basic/otherqualificationname";
    },

    ageFilterSummary() {
      if (!this.ageFilter.type) return "";

      switch (this.ageFilter.type) {
        case "greater-than":
          return `Age greater than ${this.ageFilter.minAge || "?"}`;
        case "less-than":
          return `Age less than ${this.ageFilter.maxAge || "?"}`;
        case "range":
          return `Age between ${this.ageFilter.minAge || "?"} and ${this
            .ageFilter.maxAge || "?"}`;
        case "exact":
          return `Exact age: ${this.ageFilter.exactAge || "?"}`;
        default:
          return "";
      }
    },

    pagedNeeds() {
      const start = (this.page - 1) * this.itemsPerPage;
      return this.filteredNeeds.slice(start, start + this.itemsPerPage);
    },
    totalPages() {
      return Math.ceil(this.filteredNeeds.length / this.itemsPerPage) || 1;
    },
    pagedRecommendations() {
      const start = (this.recommendationPage - 1) * this.recommendationsPerPage;
      return this.myRecommendations.slice(
        start,
        start + this.recommendationsPerPage,
      );
    },
    totalRecommendationPages() {
      return (
        Math.ceil(this.totalRecommendations / this.recommendationsPerPage) || 1
      );
    },
    recommendationStartIndex() {
      return (this.recommendationPage - 1) * this.recommendationsPerPage;
    },
    recommendationEndIndex() {
      const end = this.recommendationPage * this.recommendationsPerPage;
      return Math.min(end, this.totalRecommendations);
    },
    selectedDeps() {
      let deps = [];
      for (let need of this.trainingNeeds) {
        if (
          this.selectedNeedIds.includes(need.id) &&
          !deps.find((dep) => dep.code == need.department.code)
        ) {
          deps.push({
            code: need.department.code,
            display: need.department.display,
            totalParticipants:
              this.departmentParticipants[need.department.code] || null,
          });
        }
      }
      return deps;
    },
    selectedFacilities() {
      var seen = new Set();
      var result = [];
      var facMap = {};
      this.allowedFacilities.forEach(function(f) {
        facMap[f.id] = f.name;
      });
      for (var i = 0; i < this.trainingNeeds.length; i++) {
        var need = this.trainingNeeds[i];
        if (!this.selectedNeedIds.includes(need.id)) continue;
        (need.facilityIds || []).forEach(function(id) {
          if (!seen.has(id)) {
            seen.add(id);
            result.push({ id: id, name: facMap[id] || id });
          }
        });
      }
      return result;
    },
    hasActiveFilters() {
      return this.searchQuery || this.selectedCadre.length > 0;
    },
    durationValidationMessage() {
      if (
        !this.recommendationData.startdate ||
        !this.recommendationData.enddate ||
        !this.recommendationData.trainingtype
      ) {
        return null;
      }

      const startDate = this.$moment(this.recommendationData.startdate);
      const endDate = this.$moment(this.recommendationData.enddate);
      // const endFinancial = this.$moment(this.financialYear.end);
      const today = this.$moment().startOf("day");

      if (!startDate.isValid() || !endDate.isValid()) {
        return null;
      }

      if (startDate.isBefore(today)) {
        return "Start date can not be in the past";
      }

      // Check if start date is after end date
      if (startDate.isAfter(endDate)) {
        return "Start date can not be after End date";
      }

      // if (startDate.isAfter(endFinancial)) {
      //   return (
      //     "Start date can not be after the current financial year " +
      //     endFinancial.format("DD-MM-YYYY")
      //   );
      // }

      const durationMonths = endDate.diff(startDate, "months", true);
      const trainingType = this.recommendationData.trainingtype;

      switch (trainingType) {
        case "shortterm":
          if (durationMonths > 6) {
            return `Short-term training cannot exceed 6 months (selected duration: ${durationMonths.toFixed(
              1,
            )} months)`;
          }
          break;
        case "longterm":
          if (durationMonths <= 6) {
            return `Long-term training must be greater than 6 months (selected duration: ${durationMonths.toFixed(
              1,
            )} months)`;
          }
          break;
        // parttime - no validation needed (any duration allowed)
        default:
          return null;
      }

      return null;
    },

    isDurationValid() {
      if (
        !this.recommendationData.startdate ||
        !this.recommendationData.enddate ||
        !this.recommendationData.trainingtype
      ) {
        return true; // Not enough data to validate
      }

      const startDate = this.$moment(this.recommendationData.startdate);
      const endDate = this.$moment(this.recommendationData.enddate);
      // const endFinancial = this.$moment(this.financialYear.end);
      const today = this.$moment().startOf("day");

      if (!startDate.isValid() || !endDate.isValid()) {
        return true;
      }

      if (startDate.isBefore(today)) {
        return false;
      }

      // Check if start date is after end date
      if (startDate.isAfter(endDate)) {
        return false;
      }

      // if (startDate.isAfter(endFinancial)) {
      //   return false;
      // }

      const durationMonths = endDate.diff(startDate, "months", true);
      const trainingType = this.recommendationData.trainingtype;

      switch (trainingType) {
        case "shortterm":
          return durationMonths <= 6;
        case "longterm":
          return durationMonths > 6;
        case "parttime":
          return true;
        default:
          return true;
      }
    },

    durationInMonths() {
      if (
        !this.recommendationData.startdate ||
        !this.recommendationData.enddate
      ) {
        return null;
      }

      const startDate = this.$moment(this.recommendationData.startdate);
      const endDate = this.$moment(this.recommendationData.enddate);

      if (!startDate.isValid() || !endDate.isValid()) {
        return null;
      }

      return endDate.diff(startDate, "months", true).toFixed(1);
    },
  },
  methods: {
    async checkAccess() {
      try {
        const practitionerId =
          this.loggedInStaff && this.loggedInStaff.practitioner;
        if (!practitionerId) {
          this.accessChecked = true;
          return;
        }

        const resp = await fetch("/site/general/getHR/" + practitionerId);
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const hrList = await resp.json();

        const matched = Array.isArray(hrList)
          ? hrList.find((h) =>
              h.practitioners.find((p) => p === practitionerId),
            )
          : null;

        if (!matched) {
          this.isHR = false;
          this.accessChecked = true;
          return;
        }

        this.isHR = true;

        const coverageArr = Array.isArray(matched.coverage)
          ? matched.coverage
          : [];
        this.allowedFacilities = coverageArr.map(function(f) {
          return { id: f.id, name: f.name };
        });
      } catch (err) {
        console.error("checkAccess error:", err);
        this.showSnackbar("Failed to verify HOD access.", "error");
        this.isHR = false;
      } finally {
        this.accessChecked = true;
      }
    },
    canEdit(recommendation) {
      if (this.$moment(recommendation.startDate).isAfter(this.$moment())) {
        return true;
      }
      return false;
    },

    async loadMyRecommendations() {
      this.loadingRecommendations = true;
      try {
        let needs = await this.trainingNeeds.map((need) => need.id);
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/training-recommendation-profile",
          trainingneed: needs.join(","),
          enddate: `ge${this.$moment().format("YYYY-MM-DD")}`,
          _sort: "-_lastUpdated",
          _count: "500",
        });
        let response = await fetch("/fhir/Basic?" + params);
        let results = await response.json();
        this.myRecommendations = [];

        if (results && results.entry && results.entry.length > 0) {
          this.totalRecommendations = results.total || results.entry.length;

          for (let entry of results.entry) {
            let resource = entry.resource;
            let extension = resource.extension;

            let recommendation = {
              id: resource.id,
              resourceRef: "Basic/" + resource.id,
              title:
                extension.find((ext) => {
                  return (
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
                  );
                })?.valueString || "Untitled",

              institution: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/planning-institution"
                );
              })?.valueString,

              qualificationLevel: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/qualification-level"
                );
              })?.valueCoding,

              qualificationName: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/qualification-name"
                );
              })?.valueReference,

              qualificationNameOther: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/qualification-name-other"
                );
              })?.valueString,

              country: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/country"
                );
              })?.valueCoding,

              trainingtype: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/training-type"
                );
              })?.valueCoding?.code,

              description: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/description"
                );
              })?.valueString,

              startDate: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/start-date"
                );
              })?.valueDate,

              endDate: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/end-date"
                );
              })?.valueDate,

              department:
                extension
                  .find((ext) => {
                    return (
                      ext.url ===
                      "http://ihris.org/fhir/StructureDefinition/training-recommendation-department"
                    );
                  })
                  ?.extension?.filter((ext) => {
                    return ext.url == "department";
                  })
                  ?.map((dep) => dep.valueCoding.display)
                  ?.join(",") || "N/A",

              departmentCode: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/training-recommendation-department"
                );
              })?.valueCoding?.code,

              totalParticipants: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/total-participants"
                );
              })?.valueInteger,

              location: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/training-location"
                );
              })?.valueString,

              methodology: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/learning-methodology"
                );
              })?.valueCoding?.display,

              methodologyCode: extension.find((ext) => {
                return (
                  ext.url ===
                  "http://ihris.org/fhir/StructureDefinition/learning-methodology"
                );
              })?.valueCoding?.code,

              // Store training need IDs if available
              trainingNeedIds: extension
                .filter(
                  (ext) =>
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/training-need-reference",
                )
                .map((ext) => ext.valueReference?.reference?.split("/")[1])
                .filter(Boolean),

              // Extract designation references
              designationRefs: extension
                .filter(
                  (ext) =>
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/designation",
                )
                .map((ext) => ext.valueReference)
                .filter(Boolean),

              // Extract qualification criteria
              qualificationData: extension
                .filter(
                  (ext) =>
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/training-recommendation-qualification",
                )
                .map((ext) => {
                  const q = ext.extension || [];
                  const lvl = q.find((e) => e.url === "qualification-level")
                    ?.valueCoding;
                  return {
                    code: lvl?.code || null,
                    system: lvl?.system || null,
                    display: lvl?.display || null,
                    condition:
                      q.find((e) => e.url === "condition")?.valueString ||
                      "atleast",
                  };
                })
                .filter((q) => q.code),

              // Extract age data
              ageData: extension
                .filter(
                  (ext) =>
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/training-recommendation-age",
                )
                .map((ext) => {
                  // Extract age criteria from extension
                  const ageExt = ext.extension || [];
                  const typeExt = ageExt.find((e) => e.url === "condition");
                  const valueExt = ageExt.find((e) => e.url === "exact");
                  const minValueExt = ageExt.find((e) => e.url === "min");
                  const maxValueExt = ageExt.find((e) => e.url === "max");

                  if (typeExt) {
                    const ageItem = {
                      type: typeExt.valueString,
                    };

                    if (valueExt) {
                      ageItem.value = valueExt.valueInteger;
                    }
                    if (minValueExt) {
                      ageItem.minValue = minValueExt.valueInteger;
                    }
                    if (maxValueExt) {
                      ageItem.maxValue = maxValueExt.valueInteger;
                    }
                    return ageItem;
                  }
                  return null;
                })
                .filter(Boolean),

              // Extract department data (new structure with participants per department)
              departmentData: extension
                .filter(
                  (ext) =>
                    ext.url ===
                    "http://ihris.org/fhir/StructureDefinition/training-recommendation-department",
                )
                .map((ext) => {
                  const deptExtensions = ext.extension || [];
                  const deptCodingExt = deptExtensions.find(
                    (e) => e.url === "department",
                  );
                  const participantsExt = deptExtensions.find(
                    (e) => e.url === "total-participants",
                  );

                  if (deptCodingExt && deptCodingExt.valueCoding) {
                    return {
                      department: deptCodingExt.valueCoding.code,
                      departmentDisplay: deptCodingExt.valueCoding.display,
                      totalParticipants: participantsExt?.valueInteger || null,
                    };
                  }
                  return null;
                })
                .filter(Boolean),
            };
            this.myRecommendations.push(recommendation);
          }
        } else {
          this.totalRecommendations = 0;
        }
      } catch (error) {
        console.error("Error loading recommendations:", error);
        this.showSnackbar("Error loading recommendations", "error");
        this.totalRecommendations = 0;
      } finally {
        this.loadingRecommendations = false;
      }
    },

    editRecommendation(recommendation) {
      this.incrementNeed++;
      // Set edit mode
      this.editMode = true;
      this.departmentParticipants = {};
      this.editingRecommendation = recommendation;

      // Set fhirId for update
      this.fhirId = recommendation.id;

      // Populate form with recommendation data
      this.recommendationData = {
        title: recommendation.title || "",
        institution: recommendation.institution || "",
        courselevel: recommendation.qualificationLevel || {},
        course: recommendation.qualificationName || {},
        courseother: recommendation.qualificationNameOther || "",
        country: recommendation.country || {},
        trainingtype: recommendation.trainingtype,
        startdate: recommendation.startDate || "",
        enddate: recommendation.endDate || "",
        participants: recommendation.totalParticipants || "",
        location: recommendation.location || "",
        methodology: recommendation.methodologyCode || "",
        description: recommendation.description || "",
        designation: recommendation.designationRefs || [],
        age: recommendation.ageData || [],
      };
      this.course = recommendation.qualificationName || {};
      this.courselevel = recommendation.qualificationLevel || {};
      this.courseother = recommendation.qualificationNameOther || "";
      this.country = recommendation.country || {};

      // Setup designation rows based on existing data
      if (
        recommendation.designationRefs &&
        recommendation.designationRefs.length > 0
      ) {
        this.designationRows = recommendation.designationRefs.map(() => ({}));
      } else {
        this.designationRows = [{}];
      }

      // Restore qualification rows
      if (
        recommendation.qualificationData &&
        recommendation.qualificationData.length > 0
      ) {
        this.qualificationRows = recommendation.qualificationData.map((q) => ({
          level: q.code,
          condition: q.condition || "atleast",
        }));
      } else {
        this.qualificationRows = [{ level: null, condition: "atleast" }];
      }

      // Setup age rows based on existing data
      if (recommendation.ageData && recommendation.ageData.length > 0) {
        this.ageRows = recommendation.ageData.map((ageItem) => {
          const row = {
            type: ageItem.type || "",
            minAge: null,
            maxAge: null,
            exactAge: null,
          };

          if (ageItem.type === "greater-than") {
            row.minAge = ageItem.minValue;
          } else if (ageItem.type === "less-than") {
            row.maxAge = ageItem.maxValue;
          } else if (ageItem.type === "range") {
            row.minAge = ageItem.minValue;
            row.maxAge = ageItem.maxValue;
          } else if (ageItem.type === "exact") {
            row.exactAge = ageItem.value;
          }

          return row;
        });

        // Also update legacy ageFilter (for backward compatibility)
        const ageItem = recommendation.ageData[0];
        this.ageFilter.type = ageItem.type || "";
        if (ageItem.type === "greater-than") {
          this.ageFilter.minAge = ageItem.minValue;
        } else if (ageItem.type === "less-than") {
          this.ageFilter.maxAge = ageItem.maxValue;
        } else if (ageItem.type === "range") {
          this.ageFilter.minAge = ageItem.minValue;
          this.ageFilter.maxAge = ageItem.maxValue;
        } else if (ageItem.type === "exact") {
          this.ageFilter.exactAge = ageItem.value;
        }
      } else {
        this.ageRows = [
          { type: "", minAge: null, maxAge: null, exactAge: null },
        ];
      }

      // If there are training need IDs, select them
      if (
        recommendation.trainingNeedIds &&
        recommendation.trainingNeedIds.length > 0
      ) {
        this.selectedNeedIds = recommendation.trainingNeedIds;
        this.selectedNeed = this.trainingNeeds.filter((need) =>
          recommendation.trainingNeedIds.includes(need.id),
        );

        if (
          recommendation.departmentData &&
          recommendation.departmentData.length > 0
        ) {
          recommendation.departmentData.forEach((savedDept) => {
            this.$set(
              this.departmentParticipants,
              savedDept.department,
              savedDept.totalParticipants,
            );
          });
        }
      }

      // Scroll to form
      this.$nextTick(() => {
        this.scrollToForm();
      });

      this.showSnackbar(`Editing: ${recommendation.title}`, "info");
    },

    viewRecommendation(recommendation) {
      this.$router.push(
        "/custom/view-training-recommendation?path=/lesotho/components/training&recommendation=" +
          recommendation.id,
      );
    },

    cancelEdit() {
      this.editMode = false;
      this.editingRecommendation = null;
      this.fhirId = "";
      this.clearForm();
      this.showSnackbar("Edit cancelled", "info");
    },

    truncateText(text, maxLength) {
      if (!text) return "";
      if (text.length <= maxLength) return text;
      return text.substring(0, maxLength) + "...";
    },

    async loadTrainingNeeds() {
      this.loadingNeeds = true;
      try {
        const coveredIds = new Set(
          this.allowedFacilities.map(function(f) {
            return f.id;
          }),
        );
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/training-need-profile",
          facility: Array.from(coveredIds).join(","),
          enddate: `ge${this.$moment().format("YYYY-MM-DD")}`,
          _count: "500",
        });

        var response = await fetch("/fhir/Basic?" + params);
        response = await response.json();
        var self = this;
        this.trainingNeeds = await Promise.all(
          response.entry.map(async function(entry) {
            return await self.processTrainingNeed(entry.resource);
          }),
        );
        this.extractFilterOptions();
        this.filteredNeeds = this.trainingNeeds.slice();
      } catch (error) {
        console.error("Error loading training needs:", error);
        this.showSnackbar("Error loading training needs", "error");
      } finally {
        this.loadingNeeds = false;
      }
    },

    async processTrainingNeed(resource) {
      var need = {
        id: resource.id,
        resourceRef: "Basic/" + resource.id,
        title: "Untitled Training Need",
        description: "No description available",
        cadres: [],
        department: {},
        funder: null,
        startDate: null,
        endDate: null,
        facilityIds: [],
        created: resource.meta ? resource.meta.lastUpdated : null,
        applications: 0,
      };

      // Extract data from extensions
      if (resource.extension) {
        resource.extension.forEach(function(ext) {
          if (
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-basic-name"
          ) {
            need.title = ext.valueString || need.title;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/description"
          ) {
            need.description = ext.valueString || need.description;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/cadre"
          ) {
            if (ext.valueCoding) {
              need.cadres.push(ext.valueCoding.display || ext.valueCoding.code);
            }
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/department"
          ) {
            if (ext.valueCoding) {
              need.department = ext.valueCoding;
            }
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/start-date"
          ) {
            need.startDate = ext.valueDate;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/end-date"
          ) {
            need.endDate = ext.valueDate;
          } else if (
            ext.url === "http://ihris.org/fhir/StructureDefinition/facility"
          ) {
            if (ext.valueReference && ext.valueReference.reference) {
              need.facilityIds.push(
                ext.valueReference.reference.split("/").pop(),
              );
            }
          }
        });
      }

      return need;
    },

    extractFilterOptions() {
      var cadreSet = new Set();

      this.trainingNeeds.forEach(function(need) {
        need.cadres.forEach(function(cadre) {
          cadreSet.add(cadre);
        });
      });

      this.availableCadres = Array.from(cadreSet).map(function(cadre) {
        return {
          text: cadre,
          value: cadre,
        };
      });
    },

    // Filtering methods
    filterNeeds() {
      var self = this;
      var filtered = this.trainingNeeds.filter(function(need) {
        // Search filter
        if (self.searchQuery) {
          var query = self.searchQuery.toLowerCase();
          var matchesSearch =
            need.title.toLowerCase().includes(query) ||
            need.description.toLowerCase().includes(query) ||
            need.cadres.some(function(cadre) {
              return cadre.toLowerCase().includes(query);
            });
          if (!matchesSearch) return false;
        }

        // Cadre filter
        if (self.selectedCadre.length > 0) {
          var matchesCadre = self.selectedCadre.some(function(cadre) {
            return need.cadres.includes(cadre);
          });
          if (!matchesCadre) return false;
        }

        return true;
      });

      this.filteredNeeds = filtered;
    },

    resetFilters() {
      this.searchQuery = "";
      this.selectedCadre = [];
      this.filteredNeeds = this.trainingNeeds.slice();
    },

    // Need selection methods
    isNeedSelected(need) {
      return this.selectedNeed.find((nd) => {
        return nd.id === need.id;
      });
    },

    toggleSelectNeed(need) {
      this.incrementNeed++;
      if (this.isNeedSelected(need)) {
        let index = this.selectedNeed.findIndex((nd) => {
          return nd.id === need.id;
        });
        this.selectedNeed.splice(index, 1);
      } else {
        this.selectedNeed.push(need);
      }
    },

    toggleNeedId(needId) {
      const index = this.selectedNeedIds.indexOf(needId);
      if (index > -1) {
        this.selectedNeedIds.splice(index, 1);
        const needIndex = this.selectedNeed.findIndex((n) => n.id === needId);
        if (needIndex > -1) {
          this.selectedNeed.splice(needIndex, 1);
        }
      } else {
        this.selectedNeedIds.push(needId);
        const need = this.trainingNeeds.find((n) => n.id === needId);
        if (need && !this.selectedNeed.includes(need)) {
          this.selectedNeed.push(need);
        }
      }
    },

    deselectNeed() {
      this.selectedNeed = [];
      this.selectedNeedIds = [];
    },

    scrollToForm() {
      var formSection = this.$refs.formSection;
      if (formSection) {
        formSection.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    },

    // UI helper methods
    getEmptyStateTitle() {
      return this.trainingNeeds.length === 0
        ? "No Training Needs Available"
        : "No Matching Training Needs";
    },

    getEmptyStateMessage() {
      return this.trainingNeeds.length === 0
        ? "There are currently no training needs identified for your department."
        : "Try adjusting your filters to see more results.";
    },

    getNeedIcon(need) {
      return this.isNeedSelected(need)
        ? "mdi-check-circle"
        : "mdi-circle-outline";
    },

    getDisplayCadres(cadres, limit) {
      limit = limit || 2;
      return cadres.slice(0, limit);
    },

    getNeedHeaderClass(need) {
      return this.isNeedSelected(need) ? "primary lighten-5" : "";
    },

    getNeedCardClass(need) {
      return this.isNeedSelected(need)
        ? "elevation-4 border-primary"
        : "elevation-1";
    },

    getNeedCardStyle(need) {
      var border = this.isNeedSelected(need)
        ? "2px solid #2196F3"
        : "1px solid #e0e0e0";
      return { border: border };
    },

    getSelectButtonText(need) {
      return this.isNeedSelected(need) ? "Selected" : "Select for Application";
    },

    deptChipColor(code) {
      var map = {
        SURG: "blue lighten-5",
        HLTH: "green lighten-5",
        MCH: "pink lighten-5",
        IT: "deep-purple lighten-5",
        IPC: "orange lighten-5",
        ADMIN: "yellow lighten-4",
        HR: "light-blue lighten-5",
        FIN: "teal lighten-5",
      };
      return map[code] || "grey lighten-4";
    },

    deptTextColor(code) {
      var map = {
        SURG: "blue darken-2",
        HLTH: "green darken-2",
        MCH: "pink darken-2",
        IT: "deep-purple darken-2",
        IPC: "orange darken-2",
        ADMIN: "amber darken-3",
        HR: "light-blue darken-2",
        FIN: "teal darken-2",
      };
      return map[code] || "grey darken-1";
    },

    getFacilityName(id) {
      var fac = this.allowedFacilities.find(function(f) {
        return f.id === id;
      });
      return fac ? fac.name : id;
    },

    toggleFacilityExpand(needId) {
      this.$set(
        this.expandedFacilities,
        needId,
        !this.expandedFacilities[needId],
      );
    },

    // Date formatting methods
    formatDate(dateString, defaultValue) {
      if (!dateString) return defaultValue || "Not specified";
      try {
        var date = new Date(dateString);
        return date.toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
        });
      } catch (error) {
        return defaultValue || "Invalid date";
      }
    },

    // Form methods
    submitRequest: async function() {
      this.$refs.form.validate();
      if (!this.valid) return;

      this.submitting = true;
      this.overlay = true;
      this.fhir = {
        needs: this.selectedNeedIds,
        departments: this.selectedDeps,
        facilities: this.selectedFacilities,
        ageRows: this.ageRows,
        qualificationRows: this.qualificationRows.filter((r) => r.level),
      };

      try {
        await this.processFHIR();

        const message = this.editMode
          ? "Training recommendation updated successfully!"
          : "Training recommendation submitted successfully!";

        this.showSnackbar(message, "success");

        // Reload recommendations
        await this.loadMyRecommendations();

        // Clear form
        this.clearForm();

        // Exit edit mode
        if (this.editMode) {
          this.editMode = false;
          this.editingRecommendation = null;
        }
      } catch (error) {
        console.error("Error submitting recommendation:", error);
        this.showSnackbar("Error submitting recommendation", "error");
      } finally {
        this.submitting = false;
        this.overlay = false;
      }
    },

    clearForm() {
      if (this.$refs.form) {
        this.$refs.form.resetValidation();
      }

      this.fhirId = "";
      this.selectedNeed = [];
      this.selectedNeedIds = [];
      this.departmentParticipants = {};

      this.courselevel = null;
      this.course = null;
      this.courseother = "";
      this.country = null;

      // Reset recommendation data
      this.recommendationData = {
        title: "",
        institution: "",
        courselevel: null,
        course: null,
        courseother: "",
        country: null,
        trainingtype: "",
        startdate: "",
        enddate: "",
        participants: "",
        location: "",
        methodology: "",
        description: "",
        departments: [],
        designation: [],
        age: [],
      };

      // Reset array rows
      this.designationRows = [{}];
      this.ageRows = [{ type: "", minAge: null, maxAge: null, exactAge: null }];
      this.qualificationRows = [{ level: null, condition: "atleast" }];

      // Reset age filter (legacy - kept for compatibility)
      this.ageFilter = {
        type: "",
        minAge: null,
        maxAge: null,
        exactAge: null,
      };

      // Exit edit mode if active
      if (this.editMode) {
        this.editMode = false;
        this.editingRecommendation = null;
      }
    },

    updateAgeData() {
      // Legacy method - kept for backward compatibility
      // Now calls updateAgeDataFromRows
      this.updateAgeDataFromRows();
    },

    updateAgeDataFromRows() {
      // Build age data array from all age rows
      const ageData = [];

      this.ageRows.forEach((ageRow) => {
        if (!ageRow.type) return; // Skip empty rows

        switch (ageRow.type) {
          case "greater-than":
            if (ageRow.minAge) {
              ageData.push({
                type: "greater-than",
                value: ageRow.minAge,
              });
            }
            break;

          case "less-than":
            if (ageRow.maxAge) {
              ageData.push({
                type: "less-than",
                value: ageRow.maxAge,
              });
            }
            break;

          case "range":
            if (ageRow.minAge && ageRow.maxAge) {
              ageData.push({
                type: "range",
                minValue: ageRow.minAge,
                maxValue: ageRow.maxAge,
              });
            }
            break;

          case "exact":
            if (ageRow.exactAge) {
              ageData.push({
                type: "exact",
                value: ageRow.exactAge,
              });
            }
            break;
        }
      });

      this.recommendationData.age = ageData;
    },

    // Age row management
    addAgeRow() {
      this.ageRows.push({
        type: "",
        minAge: null,
        maxAge: null,
        exactAge: null,
      });
    },

    removeAgeRow(index) {
      if (this.ageRows.length > 1) {
        this.ageRows.splice(index, 1);
        this.updateAgeDataFromRows();
      }
    },

    addQualificationRow() {
      this.qualificationRows.push({ level: null, condition: "atleast" });
    },

    removeQualificationRow(index) {
      if (this.qualificationRows.length > 1) {
        this.qualificationRows.splice(index, 1);
      }
    },

    async loadQualificationLevels() {
      this.loadingQualificationLevels = true;
      try {
        const res = await fetch(
          "/fhir/ValueSet/qualification-level-valueset/$expand",
        );
        const data = await res.json();
        this.qualificationLevels = (data.expansion?.contains || []).map(
          (item) => ({
            code: item.code,
            system: item.system || "",
            display: item.display || item.code,
          }),
        );
      } catch (e) {
        console.error("Error loading qualification levels:", e);
      } finally {
        this.loadingQualificationLevels = false;
      }
    },

    getAgeSummary(ageRow) {
      if (!ageRow.type) return "";

      switch (ageRow.type) {
        case "greater-than":
          return `Age greater than ${ageRow.minAge || "?"}`;
        case "less-than":
          return `Age less than ${ageRow.maxAge || "?"}`;
        case "range":
          return `Age between ${ageRow.minAge || "?"} and ${ageRow.maxAge ||
            "?"}`;
        case "exact":
          return `Exact age: ${ageRow.exactAge || "?"}`;
        default:
          return "";
      }
    },

    // Designation row management
    addDesignationRow() {
      this.designationRows.push({});
      if (!this.recommendationData.designation) {
        this.recommendationData.designation = [];
      }
      this.recommendationData.designation.push(null);
    },

    removeDesignationRow(index) {
      if (this.designationRows.length > 1) {
        this.designationRows.splice(index, 1);
        this.recommendationData.designation.splice(index, 1);
      }
    },

    getTotalDepartmentParticipants() {
      return Object.values(this.departmentParticipants).reduce(
        (total, participants) => {
          return total + (parseInt(participants) || 0);
        },
        0,
      );
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },
    // Event handlers for FHIR components
    onTrainingTypeSelected(value) {
      this.recommendationData.trainingtype = value;
    },

    onStartDateSelected(value) {
      this.recommendationData.startdate = value;
    },

    onEndDateSelected(value) {
      this.recommendationData.enddate = value;
    },
  },

  components: {
    "fhir-choice": () => import("@/components/fhir/fhir-choice"),
    "fhir-string": () => import("@/components/fhir/fhir-string"),
    "fhir-date": () => import("@/components/fhir/fhir-date"),
    "fhir-reference": () => import("@/components/fhir/fhir-reference"),
    "ihris-questionnaire-section": () =>
      import("@/components/ihris/ihris-questionnaire-section"),
  },

  watch: {
    trainingNeeds: {
      immediate: true,
      handler: function() {
        this.filterNeeds();
      },
    },
  },

  // eventBus listeners registered in created so FHIR components can emit immediately
  created() {
    eventBus.$on("Basic.trainingtype", (value) => {
      value = value?.split("#")[1];
      this.onTrainingTypeSelected(value);
    });
    eventBus.$on("Basic.startDate", (value) => {
      this.onStartDateSelected(value);
    });
    eventBus.$on("Basic.endDate", (value) => {
      this.onEndDateSelected(value);
    });
    eventBus.$on("Basic.courselevel", (value) => {
      this.courselevel = value;
    });
    eventBus.$on("Basic.course", (value) => {
      this.course =
        typeof value === "string" ? { reference: value } : value || null;
    });
    eventBus.$on("Basic.courseother", (value) => {
      this.courseother = value;
    });
    eventBus.$on("Basic.country", (value) => {
      this.country = value;
    });
  },

  async mounted() {
    this.loading = true;

    await this.$nextTick();

    // Wait for generalMixin to finish loading user data
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        console.warn("Timeout waiting for user data to load");
        resolve();
      }, 15000);
    });

    await this.checkAccess();

    if (this.isHR) {
      // Fetch financial year
      try {
        let response = await fetch("/site/leave/getFinancialYear");
        this.financialYear = await response.json();
      } catch (err) {
        console.error("loadFinancialYear error:", err);
      }

      // Initialize arrays if needed
      if (!this.recommendationData.designation)
        this.recommendationData.designation = [];
      if (!this.recommendationData.age) this.recommendationData.age = [];

      await this.loadTrainingNeeds();
      await this.loadMyRecommendations();
      await this.loadQualificationLevels();
    }

    this.loading = false;
  },
};
</script>

